    const id = u.searchParams.get('id'), r = id ? await env.DB.prepare('SELECT id,title,platform,source_url,page_content FROM ci_programs WHERE id=?').bind(id).first() : null;
    if (u.pathname === '/api/ci/ai/prompt') return Response.json({ prompt: ciAiPrompt(r, ciCtx(await ciSettings(env))) }, { headers: { 'cache-control': 'no-store' } });
    const busy = async () => (await ciAiTake(env)) ? null : Response.json({ error: `Batas AI harian Competitor Intelligence (${ciAiLimit(env)}x) sudah tercapai. Coba lagi besok pukul 07.00 WIB, atau pakai "Isi dengan Claude".` }, { status: 429 });
    const aiErr = (e) => { if (e instanceof AiError) return Response.json({ error: e.message }, { status: 503 }); throw e; };
    // draf "Mengapa penting?" & "Apa yang bisa dilakukan" satu promo (tidak disimpan; tampilan yang menyimpan)
