      const p = id ? await env.DB.prepare(`SELECT ${CI_LIST_COLS} FROM ci_programs WHERE id=?`).bind(id).first() : null;
      if (!p) return Response.json({ error: 'Promo tidak ditemukan' }, { status: 404 });
      const lim = await busy(); if (lim) return lim;
